<?php
declare(strict_types=1);
$root=dirname(__DIR__);$version=$argv[1]??'1.0.0';$out=$root.'/storage/releases/les-sens-'.$version.'.zip';if(!class_exists('ZipArchive')){fwrite(STDERR,"ZipArchive no disponible\n");exit(1);}if(!is_dir(dirname($out)))mkdir(dirname($out),0750,true);$zip=new ZipArchive();$zip->open($out,ZipArchive::CREATE|ZipArchive::OVERWRITE);$excluded=['.env','.git','.codex','.agents','storage','tests','docs','database/seed.sql'];$manifest=[];$it=new RecursiveIteratorIterator(new RecursiveDirectoryIterator($root,FilesystemIterator::SKIP_DOTS));foreach($it as $file){if(!$file->isFile())continue;$rel=str_replace('\\','/',substr($file->getPathname(),strlen($root)+1));$skip=false;foreach($excluded as $prefix){if($rel===$prefix||str_starts_with($rel,$prefix.'/')){$skip=true;break;}}if($skip||str_ends_with($rel,'.zip'))continue;$zip->addFile($file->getPathname(),$rel);$manifest[$rel]=hash_file('sha256',$file->getPathname());}$manifest['_release']=['version'=>$version,'created_at'=>gmdate('c'),'excluded'=>$excluded];$zip->addFromString('RELEASE_MANIFEST.json',json_encode($manifest,JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE));$zip->close();$sha=hash_file('sha256',$out);file_put_contents($out.'.sha256',$sha.'  '.basename($out).PHP_EOL);echo json_encode(['package'=>$out,'sha256'=>$sha,'files'=>count($manifest)-1],JSON_PRETTY_PRINT).PHP_EOL;
